"""Regenerate references/toolbelt.md from data/atlas.jsonl (run after `atlas.py refresh`)."""
import collections, json, os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.join(HERE, "..")
rows = [json.loads(l) for l in open(os.path.join(ROOT, "data", "atlas.jsonl"), encoding="utf-8")]
by = collections.defaultdict(list)
for r in rows:
    if r.get("policy") != "blocked":
        by[r["category"]].append(r)
order = sorted(by, key=lambda c: -sum(r["value_for_claude"] for r in by[c]))
out = ["# Toolbelt: best picks per category", "",
       "Generated by `scripts/build_toolbelt.py` from `data/atlas.jsonl` (top 1000 GitHub repos by stars, pulled 2026-11-11). "
       "Ranked by value_for_claude, then relevance to media/design/RE/AI work, then stars; archived repos sink. "
       "A `?` in the install column means the command was not confirmed in the README: check before running.", ""]
for c in order:
    picks = sorted(by[c], key=lambda r: (r.get("alive") == "archived", -r["value_for_claude"],
                                         -r["owner_relevance"], -r["stars"]))[:10]
    picks = [r for r in picks if r["value_for_claude"] >= 2]
    if not picks:
        continue
    out += [f"## {c} ({len(by[c])} repos)", "", "| repo | stars | use when | Windows install |", "|---|---|---|---|"]
    for r in picks:
        tags = (["archived"] if r.get("alive") == "archived" else []) + (["consent"] if r.get("policy") == "consent" else [])
        t = f" _({', '.join(tags)})_" if tags else ""
        inst = (r.get("install_windows") or "").replace("\n", " ")[:110].replace("|", "\\|")
        use = (r.get("use_when") or "").replace("|", "/")[:150]
        out.append(f"| [{r['repo']}]({r['url']}){t} | {r['stars'] // 1000}k | {use} | `{inst}` |")
    out.append("")
dst = os.path.join(ROOT, "references", "toolbelt.md")
open(dst, "w", encoding="utf-8").write("\n".join(out))
print("wrote", dst, len(out), "lines;", "categories:", ", ".join(order))
